//! Askama template contexts. Output is HTML-escaped by default; only `svg` (generated by us) is `|safe`.

use crate::{AppState, auth::Staff, error::AppError};
use askama::Template;
use axum::response::Html;

pub struct Ctx {
    pub outlet: String,
    pub role: String,
    pub user: String,
    pub nav: &'static str,
    pub kitchen: bool,
    pub qr: bool,
    pub theme: String,
    pub can_reports: bool,
}

impl Ctx {
    pub async fn staff(st: &AppState, s: &Staff, nav: &'static str) -> Result<Self, AppError> {
        let mut c = Self::guest(st).await?;
        c.role = s.role.as_str().into();
        c.user = s.name.clone();
        c.nav = nav;
        c.can_reports = s.can(crate::auth::Perm::Reports);
        Ok(c)
    }
    pub async fn guest(st: &AppState) -> Result<Self, AppError> {
        let (outlet, kitchen, qr, theme): (String, i64, i64, String) =
            sqlx::query_as("SELECT outlet_name, kitchen_mode, qr_ordering, theme FROM outlet_settings WHERE id = 1")
                .fetch_one(&st.db)
                .await?;
        Ok(Self {
            outlet,
            role: String::new(),
            user: String::new(),
            nav: "",
            kitchen: kitchen == 1,
            qr: qr == 1,
            theme,
            can_reports: false,
        })
    }
}

pub fn render<T: Template>(t: T) -> Result<Html<String>, AppError> {
    Ok(Html(t.render().map_err(|e| anyhow::anyhow!("template: {e}"))?))
}

